{"content":"// Station types and crisis management
import {
  World,
  Mesh,
  Group,
  BoxGeometry,
  CylinderGeometry,
  SphereGeometry,
  MeshStandardMaterial,
  MeshBasicMaterial,
  Color,
  Vector3,
  PointLight,
  RingGeometry,
  DoubleSide,
  AdditiveBlending,
  Float32BufferAttribute,
  BufferGeometry,
  LineSegments,
  LineBasicMaterial,
  PanelUI,
} from '@iwsdk/core';

export type StationType = 'reactor' | 'shields' | 'oxygen' | 'power' | 'comms';

export interface Station {
  type: StationType;
  label: string;
  color: string;
  crisis: number; // 0-100, 100 = critical failure
  crisisRate: number; // per second
  active: boolean; // currently in crisis
  resolved: number; // times resolved
  angle: number; // position angle in room
  group: Group;
  light: PointLight;
  panelEntity: ReturnType<World['createTransformEntity']> | null;
  interactTarget: Mesh;
  interactCooldown: number;
  // Station-specific state
  sequenceTarget: number[];
  sequenceInput: number[];
  pumpCount: number;
  pumpTarget: number;
  matchTarget: number[];
  matchInput: number[];
}

const STATION_DEFS: { type: StationType; label: string; color: string; angle: number }[] = [
  { type: 'reactor', label: 'REACTOR', color: '#ff3333', angle: 0 },
  { type: 'shields', label: 'SHIELDS', color: '#3399ff', angle: Math.PI * 0.4 },
  { type: 'oxygen', label: 'OXYGEN', color: '#33ff66', angle: Math.PI * 0.8 },
  { type: 'power', label: 'POWER', color: '#ffaa00', angle: Math.PI * 1.2 },
  { type: 'comms', label: 'COMMS', color: '#cc33ff', angle: Math.PI * 1.6 },
];

const STATION_RADIUS = 4;

export class StationManager {
  stations: Station[] = [];
  private world: World;

  constructor(world: World) {
    this.world = world;
  }

  build() {
    for (const def of STATION_DEFS) {
      const x = Math.sin(def.angle) * STATION_RADIUS;
      const z = -Math.cos(def.angle) * STATION_RADIUS;

      const group = new Group();
      group.position.set(x, 0, z);
      group.lookAt(0, 0, 0);

      // Station console base
      const consoleMat = new MeshStandardMaterial({
        color: new Color(0x111122),
        emissive: new Color(def.color).multiplyScalar(0.1),
        metalness: 0.8,
        roughness: 0.3,
      });

      const consoleBase = new Mesh(
        new BoxGeometry(1.6, 1.0, 0.6),
        consoleMat
      );
      consoleBase.position.set(0, 0.5, 0);
      group.add(consoleBase);

      // Console top (angled screen area)
      const consoleTop = new Mesh(
        new BoxGeometry(1.6, 0.05, 0.8),
        new MeshStandardMaterial({
          color: new Color(0x000000),
          emissive: new Color(def.color).multiplyScalar(0.05),
          metalness: 0.9,
          roughness: 0.1,
        })
      );
      consoleTop.position.set(0, 1.02, -0.1);
      consoleTop.rotation.x = -0.3;
      group.add(consoleTop);

      // Status light strip on console front
      const stripGeo = new BoxGeometry(1.4, 0.05, 0.02);
      const stripMat = new MeshBasicMaterial({
        color: new Color(def.color),
        transparent: true,
        opacity: 0.8,
      });
      const strip = new Mesh(stripGeo, stripMat);
      strip.position.set(0, 0.9, -0.31);
      group.add(strip);

      // Side pillars
      for (const side of [-1, 1]) {
        const pillar = new Mesh(
          new BoxGeometry(0.08, 1.8, 0.08),
          new MeshStandardMaterial({
            color: 0x222233,
            emissive: new Color(def.color).multiplyScalar(0.15),
            metalness: 0.7,
            roughness: 0.4,
          })
        );
        pillar.position.set(side * 0.85, 0.9, 0);
        group.add(pillar);

        // Top cap light
        const cap = new Mesh(
          new SphereGeometry(0.06, 8, 8),
          new MeshBasicMaterial({ color: new Color(def.color) })
        );
        cap.position.set(side * 0.85, 1.85, 0);
        group.add(cap);
      }

      // Interaction target (invisible large hit area)
      const interactTarget = new Mesh(
        new BoxGeometry(1.8, 1.5, 1.0),
        new MeshBasicMaterial({ visible: false })
      );
      interactTarget.position.set(0, 0.75, 0);
      group.add(interactTarget);

      // Station point light
      const light = new PointLight(new Color(def.color), 0.5, 6);
      light.position.set(0, 2.0, -0.5);
      group.add(light);

      this.world.scene.add(group);

      // Create panel entity for UI
      const panelGroup = new Group();
      panelGroup.position.set(0, 1.4, -0.15);
      panelGroup.rotation.x = -0.2;
      panelGroup.scale.set(0.7, 0.7, 0.7);
      group.add(panelGroup);

      const panelEntity = this.world.createTransformEntity(panelGroup);
      panelEntity.addComponent(PanelUI, {
        config: `./ui/${def.type}.json`,
        width: 0.5,
        height: 0.35,
      });

      const station: Station = {
        type: def.type,
        label: def.label,
        color: def.color,
        crisis: 0,
        crisisRate: 3 + Math.random() * 2, // 3-5 per second base
        active: false,
        resolved: 0,
        angle: def.angle,
        group,
        light,
        panelEntity,
        interactTarget,
        interactCooldown: 0,
        sequenceTarget: [],
        sequenceInput: [],
        pumpCount: 0,
        pumpTarget: 8,
        matchTarget: [],
        matchInput: [],
      };

      this.stations.push(station);
    }
  }

  getStation(type: StationType): Station | undefined {
    return this.stations.find(s => s.type === type);
  }

  resetStation(station: Station) {
    station.crisis = 0;
    station.active = false;
    station.sequenceTarget = [];
    station.sequenceInput = [];
    station.pumpCount = 0;
    station.matchTarget = [];
    station.matchInput = [];
    station.interactCooldown = 0;
  }

  activateStation(station: Station) {
    station.active = true;
    station.crisis = 20 + Math.random() * 20;

    // Set up station-specific challenge
    switch (station.type) {
      case 'reactor': {
        // Press 3-5 buttons in sequence
        const len = 3 + Math.floor(Math.random() * 3);
        station.sequenceTarget = Array.from({ length: len }, () => Math.floor(Math.random() * 4));
        station.sequenceInput = [];
        break;
      }
      case 'shields': {
        // Rapid trigger pulls
        station.pumpCount = 0;
        station.pumpTarget = 6 + Math.floor(Math.random() * 5);
        break;
      }
      case 'oxygen': {
        // Rapid trigger pumping
        station.pumpCount = 0;
        station.pumpTarget = 8 + Math.floor(Math.random() * 6);
        break;
      }
      case 'power': {
        // Match 3-4 colored switches
        const len = 3 + Math.floor(Math.random() * 2);
        station.matchTarget = Array.from({ length: len }, () => Math.floor(Math.random() * 4));
        station.matchInput = [];
        break;
      }
      case 'comms': {
        // Repeat signal pattern
        const len = 3 + Math.floor(Math.random() * 3);
        station.sequenceTarget = Array.from({ length: len }, () => Math.floor(Math.random() * 4));
        station.sequenceInput = [];
        break;
      }
    }
  }
}
","path":"workspace/neon-panic/src/stations.ts"}

{"content":"// Environment setup - holodeck aesthetic
import {
  World,
  Mesh,
  Group,
  BoxGeometry,
  CylinderGeometry,
  SphereGeometry,
  RingGeometry,
  MeshStandardMaterial,
  MeshBasicMaterial,
  LineSegments,
  LineBasicMaterial,
  EdgesGeometry,
  BufferGeometry,
  Float32BufferAttribute,
  Color,
  Vector3,
  AmbientLight,
  PointLight,
  DirectionalLight,
  Fog,
  DoubleSide,
  AdditiveBlending,
  Points,
  PointsMaterial,
} from '@iwsdk/core';

export class Environment {
  private world: World;

  constructor(world: World) {
    this.world = world;
  }

  build() {
    const scene = this.world.scene;

    // Dark space station fog
    scene.fog = new Fog(0x000811, 8, 30);
    scene.background = new Color(0x000811);

    // Ambient light
    scene.add(new AmbientLight(0x112233, 0.3));

    // Central overhead light
    const overhead = new PointLight(0x4466aa, 1.5, 15);
    overhead.position.set(0, 4, 0);
    scene.add(overhead);

    // Floor - hex grid pattern
    this.buildFloor(scene);

    // Walls - curved station walls
    this.buildWalls(scene);

    // Ceiling
    this.buildCeiling(scene);

    // Central command pillar
    this.buildCenterPillar(scene);

    // Ambient particles (floating dust/sparks)
    this.buildParticles(scene);
  }

  private buildFloor(scene: Group) {
    // Main floor disc
    const floorGeo = new CylinderGeometry(7, 7, 0.05, 32);
    const floorMat = new MeshStandardMaterial({
      color: 0x0a0a1a,
      metalness: 0.9,
      roughness: 0.3,
      emissive: new Color(0x111133),
      emissiveIntensity: 0.1,
    });
    const floor = new Mesh(floorGeo, floorMat);
    floor.position.y = -0.025;
    scene.add(floor);

    // Grid lines on floor
    const gridLines = new Group();
    const gridMat = new LineBasicMaterial({
      color: 0x1a2244,
      transparent: true,
      opacity: 0.4,
    });

    // Concentric rings
    for (let r = 1; r <= 6; r++) {
      const ringGeo = new BufferGeometry();
      const pts: number[] = [];
      for (let i = 0; i <= 64; i++) {
        const a = (i / 64) * Math.PI * 2;
        pts.push(Math.cos(a) * r, 0.01, Math.sin(a) * r);
      }
      ringGeo.setAttribute('position', new Float32BufferAttribute(pts, 3));
      gridLines.add(new LineSegments(ringGeo, gridMat));
    }

    // Radial lines
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * Math.PI * 2;
      const geo = new BufferGeometry();
      geo.setAttribute('position', new Float32BufferAttribute([
        0, 0.01, 0,
        Math.cos(a) * 7, 0.01, Math.sin(a) * 7,
      ], 3));
      gridLines.add(new LineSegments(geo, gridMat));
    }

    scene.add(gridLines);
  }

  private buildWalls(scene: Group) {
    // Segmented curved walls
    const wallSegments = 24;
    const wallRadius = 6.5;
    const wallHeight = 3.5;

    for (let i = 0; i < wallSegments; i++) {
      const a = (i / wallSegments) * Math.PI * 2;
      const x = Math.sin(a) * wallRadius;
      const z = -Math.cos(a) * wallRadius;

      const panel = new Mesh(
        new BoxGeometry(1.6, wallHeight, 0.08),
        new MeshStandardMaterial({
          color: 0x0d0d22,
          metalness: 0.8,
          roughness: 0.4,
          emissive: new Color(0x0a1530),
          emissiveIntensity: 0.2,
        })
      );
      panel.position.set(x, wallHeight / 2, z);
      panel.lookAt(0, wallHeight / 2, 0);
      scene.add(panel);

      // Horizontal accent strips on every other panel
      if (i % 2 === 0) {
        const strip = new Mesh(
          new BoxGeometry(1.5, 0.02, 0.09),
          new MeshBasicMaterial({
            color: 0x2244aa,
            transparent: true,
            opacity: 0.5,
          })
        );
        strip.position.set(x, 1.5, z);
        strip.lookAt(0, 1.5, 0);
        scene.add(strip);
      }
    }
  }

  private buildCeiling(scene: Group) {
    const ceilGeo = new CylinderGeometry(7, 7, 0.1, 32);
    const ceilMat = new MeshStandardMaterial({
      color: 0x080818,
      metalness: 0.9,
      roughness: 0.2,
    });
    const ceiling = new Mesh(ceilGeo, ceilMat);
    ceiling.position.y = 3.5;
    scene.add(ceiling);

    // Ceiling light ring
    const ringGeo = new RingGeometry(2, 2.3, 32);
    const ringMat = new MeshBasicMaterial({
      color: 0x3355aa,
      transparent: true,
      opacity: 0.6,
      side: DoubleSide,
    });
    const ring = new Mesh(ringGeo, ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 3.44;
    scene.add(ring);
  }

  private buildCenterPillar(scene: Group) {
    // Central command pillar
    const pillar = new Mesh(
      new CylinderGeometry(0.3, 0.4, 3.5, 8),
      new MeshStandardMaterial({
        color: 0x111133,
        metalness: 0.9,
        roughness: 0.2,
        emissive: new Color(0x0a1540),
        emissiveIntensity: 0.3,
      })
    );
    pillar.position.y = 1.75;
    scene.add(pillar);

    // Rotating ring around pillar
    const holoRing = new Mesh(
      new RingGeometry(0.5, 0.55, 32),
      new MeshBasicMaterial({
        color: 0x44aaff,
        transparent: true,
        opacity: 0.4,
        side: DoubleSide,
      })
    );
    holoRing.rotation.x = Math.PI / 2;
    holoRing.position.y = 2.5;
    scene.add(holoRing);

    // Top beacon
    const beacon = new Mesh(
      new SphereGeometry(0.15, 16, 16),
      new MeshBasicMaterial({
        color: 0x44aaff,
        transparent: true,
        opacity: 0.8,
      })
    );
    beacon.position.y = 3.3;
    scene.add(beacon);

    const beaconLight = new PointLight(0x44aaff, 0.8, 8);
    beaconLight.position.y = 3.3;
    scene.add(beaconLight);
  }

  private buildParticles(scene: Group) {
    const count = 200;
    const positions = new Float32Array(count * 3);

    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 1 + Math.random() * 5;
      positions[i * 3] = Math.cos(a) * r;
      positions[i * 3 + 1] = 0.5 + Math.random() * 2.5;
      positions[i * 3 + 2] = Math.sin(a) * r;
    }

    const geo = new BufferGeometry();
    geo.setAttribute('position', new Float32BufferAttribute(positions, 3));

    const particles = new Points(
      geo,
      new PointsMaterial({
        color: 0x4488ff,
        size: 0.015,
        transparent: true,
        opacity: 0.4,
        blending: AdditiveBlending,
        depthWrite: false,
      })
    );
    scene.add(particles);
  }
}
